import{_ as e,o as s,c as n,ag as t}from"./chunks/framework.BpFM782D.js";const h=JSON.parse('{"title":"workflow","description":"","frontmatter":{},"headers":[],"relativePath":"commands/ccg-workflow.md","filePath":"commands/ccg-workflow.md","lastUpdated":null}'),o={name:"commands/ccg-workflow.md"};function l(i,a,d,p,c,r){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="workflow" tabindex="-1">workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;workflow&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>workflow</td></tr><tr><td>說明</td><td>多模型协作开发工作流（研究→构思→计划→执行→优化→评审），智能路由前端→Gemini、后端→Codex</td></tr><tr><td>系列</td><td>CCG</td></tr><tr><td>來源檔案</td><td><code>commands/ccg/workflow.md</code></td></tr></tbody></table><hr><h1 id="workflow-多模型协作开发" tabindex="-1">Workflow - 多模型协作开发 <a class="header-anchor" href="#workflow-多模型协作开发" aria-label="Permalink to &quot;Workflow - 多模型协作开发&quot;">​</a></h1><p>使用质量把关、MCP 服务和多模型协作执行结构化开发工作流。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/workflow</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">任务描</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">述</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><ul><li>要开发的任务：$ARGUMENTS</li><li>带质量把关的结构化 6 阶段工作流</li><li>多模型协作：Codex（后端）+ Gemini（前端）+ Claude（编排）</li><li>MCP 服务集成（ace-tool）以增强功能</li></ul><h2 id="你的角色" tabindex="-1">你的角色 <a class="header-anchor" href="#你的角色" aria-label="Permalink to &quot;你的角色&quot;">​</a></h2><p>你是<strong>编排者</strong>，协调多模型协作系统（研究 → 构思 → 计划 → 执行 → 优化 → 评审），用中文协助用户，面向专业程序员，交互应简洁专业，避免不必要解释。</p><p><strong>协作模型</strong>：</p><ul><li><strong>Codex</strong> – 后端逻辑、算法、调试（<strong>后端权威，可信赖</strong>）</li><li><strong>Gemini</strong> – 前端 UI/UX、视觉设计（<strong>前端高手，后端意见仅供参考</strong>）</li><li><strong>Claude (自己)</strong> – 编排、计划、执行、交付</li></ul><hr><h2 id="多模型调用规范" tabindex="-1">多模型调用规范 <a class="header-anchor" href="#多模型调用规范" aria-label="Permalink to &quot;多模型调用规范&quot;">​</a></h2><p><strong>工作目录</strong>：</p><ul><li><code>&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;</code>：替换为目标工作目录的<strong>绝对路径</strong></li><li>如果用户通过 <code>/add-dir</code> 添加了多个工作区，先用 Glob/Grep 确定任务相关的工作区</li><li>如果无法确定，用 <code>AskUserQuestion</code> 询问用户选择目标工作区</li><li>默认使用当前工作目录</li></ul><p><strong>调用语法</strong>（并行用 <code>run_in_background: true</code>，串行用 <code>false</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 新会话调用</span></span>
<span class="line"><span>Bash({</span></span>
<span class="line"><span>  command: &quot;/Users/ericcai/.claude/bin/codeagent-wrapper --backend &amp;lt;codex|gemini&gt; &amp;#123;&amp;#123;GEMINI_MODEL_FLAG&amp;#125;&amp;#125;- \\&quot;&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;\\&quot; &lt;&lt;&#39;EOF&#39;</span></span>
<span class="line"><span>ROLE_FILE: &lt;角色提示词路径&gt;</span></span>
<span class="line"><span>&amp;lt;TASK&gt;</span></span>
<span class="line"><span>需求：&lt;增强后的需求（如未增强则用 $ARGUMENTS）&gt;</span></span>
<span class="line"><span>上下文：&lt;前序阶段收集的项目上下文、分析结果等&gt;</span></span>
<span class="line"><span>&amp;lt;/TASK&gt;</span></span>
<span class="line"><span>OUTPUT: 期望输出格式</span></span>
<span class="line"><span>EOF&quot;,</span></span>
<span class="line"><span>  run_in_background: true,</span></span>
<span class="line"><span>  timeout: 3600000,</span></span>
<span class="line"><span>  description: &quot;简短描述&quot;</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 复用会话调用</span></span>
<span class="line"><span>Bash({</span></span>
<span class="line"><span>  command: &quot;/Users/ericcai/.claude/bin/codeagent-wrapper --backend &amp;lt;codex|gemini&gt; &amp;#123;&amp;#123;GEMINI_MODEL_FLAG&amp;#125;&amp;#125;resume &amp;lt;SESSION_ID&gt; - \\&quot;&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;\\&quot; &lt;&lt;&#39;EOF&#39;</span></span>
<span class="line"><span>ROLE_FILE: &lt;角色提示词路径&gt;</span></span>
<span class="line"><span>&amp;lt;TASK&gt;</span></span>
<span class="line"><span>需求：&lt;增强后的需求（如未增强则用 $ARGUMENTS）&gt;</span></span>
<span class="line"><span>上下文：&lt;前序阶段收集的项目上下文、分析结果等&gt;</span></span>
<span class="line"><span>&amp;lt;/TASK&gt;</span></span>
<span class="line"><span>OUTPUT: 期望输出格式</span></span>
<span class="line"><span>EOF&quot;,</span></span>
<span class="line"><span>  run_in_background: true,</span></span>
<span class="line"><span>  timeout: 3600000,</span></span>
<span class="line"><span>  description: &quot;简短描述&quot;</span></span>
<span class="line"><span>})</span></span></code></pre></div><p><strong>模型参数说明</strong>：</p><ul><li><code>&amp;#123;&amp;#123;GEMINI_MODEL_FLAG&amp;#125;&amp;#125;</code>：当使用 <code>--backend gemini</code> 时，替换为 <code>--gemini-model gemini-3.1-pro-preview </code>（注意末尾空格）；使用 codex 时替换为空字符串</li></ul><p><strong>角色提示词</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>Codex</th><th>Gemini</th></tr></thead><tbody><tr><td>分析</td><td><code>/Users/ericcai/.claude/.ccg/prompts/codex/analyzer.md</code></td><td><code>/Users/ericcai/.claude/.ccg/prompts/gemini/analyzer.md</code></td></tr><tr><td>规划</td><td><code>/Users/ericcai/.claude/.ccg/prompts/codex/architect.md</code></td><td><code>/Users/ericcai/.claude/.ccg/prompts/gemini/architect.md</code></td></tr><tr><td>审查</td><td><code>/Users/ericcai/.claude/.ccg/prompts/codex/reviewer.md</code></td><td><code>/Users/ericcai/.claude/.ccg/prompts/gemini/reviewer.md</code></td></tr></tbody></table><p><strong>会话复用</strong>：每次调用返回 <code>SESSION_ID: xxx</code>，后续阶段用 <code>resume xxx</code> 子命令复用上下文（注意：是 <code>resume</code>，不是 <code>--resume</code>）。</p><p><strong>并行调用</strong>：使用 <code>run_in_background: true</code> 启动，用 <code>TaskOutput</code> 等待结果。<strong>必须等所有模型返回后才能进入下一阶段</strong>。</p><p><strong>等待后台任务</strong>（使用最大超时 600000ms = 10 分钟）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TaskOutput({ task_id: &quot;&amp;lt;task_id&gt;&quot;, block: true, timeout: 600000 })</span></span></code></pre></div><p><strong>重要</strong>：</p><ul><li>必须指定 <code>timeout: 600000</code>，否则默认只有 30 秒会导致提前超时。 如果 10 分钟后仍未完成，继续用 <code>TaskOutput</code> 轮询，<strong>绝对不要 Kill 进程</strong>。</li><li>若因等待时间过长跳过了等待 TaskOutput 结果，则<strong>必须调用 <code>AskUserQuestion</code> 工具询问用户选择继续等待还是 Kill Task。禁止直接 Kill Task。</strong></li></ul><hr><h2 id="沟通守则" tabindex="-1">沟通守则 <a class="header-anchor" href="#沟通守则" aria-label="Permalink to &quot;沟通守则&quot;">​</a></h2><ol><li>响应以模式标签 <code>[模式：X]</code> 开始，初始为 <code>[模式：研究]</code>。</li><li>核心工作流严格按 <code>研究 → 构思 → 计划 → 执行 → 优化 → 评审</code> 顺序流转。</li><li>每个阶段完成后必须请求用户确认。</li><li>评分低于 7 分或用户未批准时强制停止。</li><li>在需要询问用户时，尽量使用 <code>AskUserQuestion</code> 工具进行交互，举例场景：请求用户确认/选择/批准</li></ol><hr><h2 id="执行工作流" tabindex="-1">执行工作流 <a class="header-anchor" href="#执行工作流" aria-label="Permalink to &quot;执行工作流&quot;">​</a></h2><p><strong>任务描述</strong>：$ARGUMENTS</p><h3 id="🔍-阶段-1-研究与分析" tabindex="-1">🔍 阶段 1：研究与分析 <a class="header-anchor" href="#🔍-阶段-1-研究与分析" aria-label="Permalink to &quot;🔍 阶段 1：研究与分析&quot;">​</a></h3><p><code>[模式：研究]</code> - 理解需求并收集上下文：</p><ol><li><strong>Prompt 增强</strong>（按 <code>/ccg:enhance</code> 的逻辑执行）：分析 $ARGUMENTS 的意图、缺失信息、隐含假设，补全为结构化需求（明确目标、技术约束、范围边界、验收标准），<strong>用增强结果替代原始 $ARGUMENTS，后续调用 Codex/Gemini 时传入增强后的需求</strong></li><li><strong>上下文检索</strong>：调用 <code>mcp__ace-tool__search_context</code></li><li><strong>需求完整性评分</strong>（0-10 分）： <ul><li>目标明确性（0-3）、预期结果（0-3）、边界范围（0-2）、约束条件（0-2）</li><li>≥7 分：继续 | &lt;7 分：⛔ 停止，提出补充问题</li></ul></li></ol><h3 id="💡-阶段-2-方案构思" tabindex="-1">💡 阶段 2：方案构思 <a class="header-anchor" href="#💡-阶段-2-方案构思" aria-label="Permalink to &quot;💡 阶段 2：方案构思&quot;">​</a></h3><p><code>[模式：构思]</code> - 多模型并行分析：</p><p><strong>并行调用</strong>（<code>run_in_background: true</code>）：</p><ul><li>Codex：使用分析提示词，输出技术可行性、方案、风险</li><li>Gemini：使用分析提示词，输出 UI 可行性、方案、体验</li></ul><p>用 <code>TaskOutput</code> 等待结果。<strong>📌 保存 SESSION_ID</strong>（<code>CODEX_SESSION</code> 和 <code>GEMINI_SESSION</code>）。</p><p><strong>务必遵循上方 <code>多模型调用规范</code> 的 <code>重要</code> 指示</strong></p><p>综合两方分析，输出方案对比（至少 2 个方案），等待用户选择。</p><h3 id="📋-阶段-3-详细规划" tabindex="-1">📋 阶段 3：详细规划 <a class="header-anchor" href="#📋-阶段-3-详细规划" aria-label="Permalink to &quot;📋 阶段 3：详细规划&quot;">​</a></h3><p><code>[模式：计划]</code> - 多模型协作规划：</p><p><strong>并行调用</strong>（复用会话 <code>resume &amp;lt;SESSION_ID&gt;</code>）：</p><ul><li>Codex：使用规划提示词 + <code>resume $CODEX_SESSION</code>，输出后端架构</li><li>Gemini：使用规划提示词 + <code>resume $GEMINI_SESSION</code>，输出前端架构</li></ul><p>用 <code>TaskOutput</code> 等待结果。</p><p><strong>务必遵循上方 <code>多模型调用规范</code> 的 <code>重要</code> 指示</strong></p><p><strong>Claude 综合规划</strong>：采纳 Codex 后端规划 + Gemini 前端规划，用户批准后存入 <code>.claude/plan/任务名.md</code></p><h3 id="⚡-阶段-4-实施" tabindex="-1">⚡ 阶段 4：实施 <a class="header-anchor" href="#⚡-阶段-4-实施" aria-label="Permalink to &quot;⚡ 阶段 4：实施&quot;">​</a></h3><p><code>[模式：执行]</code> - 代码开发：</p><ul><li>严格按批准的计划实施</li><li>遵循项目现有代码规范</li><li>在关键里程碑请求反馈</li></ul><h3 id="🚀-阶段-5-代码优化" tabindex="-1">🚀 阶段 5：代码优化 <a class="header-anchor" href="#🚀-阶段-5-代码优化" aria-label="Permalink to &quot;🚀 阶段 5：代码优化&quot;">​</a></h3><p><code>[模式：优化]</code> - 多模型并行审查：</p><p><strong>并行调用</strong>：</p><ul><li>Codex：使用审查提示词，关注安全、性能、错误处理</li><li>Gemini：使用审查提示词，关注可访问性、设计一致性</li></ul><p>用 <code>TaskOutput</code> 等待结果。整合审查意见，用户确认后执行优化。</p><p><strong>务必遵循上方 <code>多模型调用规范</code> 的 <code>重要</code> 指示</strong></p><h3 id="✅-阶段-6-质量审查" tabindex="-1">✅ 阶段 6：质量审查 <a class="header-anchor" href="#✅-阶段-6-质量审查" aria-label="Permalink to &quot;✅ 阶段 6：质量审查&quot;">​</a></h3><p><code>[模式：评审]</code> - 最终评估：</p><ul><li>对照计划检查完成情况</li><li>运行测试验证功能</li><li>报告问题与建议</li><li>请求最终用户确认</li></ul><hr><h2 id="关键规则" tabindex="-1">关键规则 <a class="header-anchor" href="#关键规则" aria-label="Permalink to &quot;关键规则&quot;">​</a></h2><ol><li>阶段顺序不可跳过（除非用户明确指令）</li><li>外部模型对文件系统<strong>零写入权限</strong>，所有修改由 Claude 执行</li><li>评分 &lt;7 或用户未批准时<strong>强制停止</strong></li></ol>`,67)])])}const g=e(o,[["render",l]]);export{h as __pageData,g as default};
